rdHrv:["HRV {0} ms (usual {1})","VFC {0} ms (normale {1})"], rdRhr:["Resting HR {0} (usual {1})","FC repos {0} (normale {1})"], rdSleep:["Sleep {0}","Sommeil {0}"],
