fitTAct:["Rebuild a workout from this session","Reconstruire une séance depuis cette sortie"], fitHintAct:["Rebuild it in absolute watts (as ridden), or as % of an FTP of your choice. In that case pick the FTP used as the reference.","Reconstruire en watts absolus (comme roulés), ou en % d'une FTP de ton choix. Dans ce cas, choisis la FTP de référence."], fitGo:["Import","Importer"], clbT:["Random climb","Col au hasard"], clbNew:["Another random climb","Un autre col au hasard"], clbPrev:["Previous climb","Col précédent"], clbNext:["Next climb","Col suivant"], clbLen:["Length","Longueur"], clbGain:["Gain","Dénivelé"], clbAvg:["Avg","Moy."], clbMax:["Steepest","Max"], clbEtaMe:["About {0} at {1} W ({2}% of your FTP), rider and bike {3} kg","Environ {0} à {1} W ({2} % de ta FTP), coureur et vélo {3} kg"], clbEtaRef:["About {0} at {1} W/kg (reference rider)","Environ {0} à {1} W/kg (coureur de référence)"], clbUse:["Use this climb","Utiliser ce col"], clbSrc:["Source:","Source :"], clbWiki:["Wikipedia","Wikipédia"], impFitNoPw:["This FIT file has no power data to rebuild a workout from.","Ce fichier FIT ne contient pas de puissance pour reconstruire une séance."], impHistLoad:["Load","Charger"],
